@rule("s129", "s130", otherwise="Contradiction")
def check_confidentiality_clause():
    return "Receiving Party shall not reverse engineer any objects which embody Disclosing Party's Confidential Information." == "Receiving Party shall not reverse engineer any objects which embody Disclosing Party's Confidential Information."

@rule("s52", "s67", otherwise="Contradiction")
def check_data_protection_clause():
    return "The Company shall take all reasonable precautions and adequate measures to preserve the integrity and prevent any corruption or loss, damage or destruction of AHPL’s data." == "The Company shall take all reasonable precautions and adequate measures to preserve the integrity and prevent any corruption or loss, damage or destruction of AHPL’s data."

@rule("s78", "s85", otherwise="Contradiction")
def check_dispute_resolution_clause():
    return "In the event of any dispute or difference arising out of or in connection with or in relation to this Agreement or the existence, validity, termination, application or interpretation of this Agreement or any of its provisions, both parties shall use their best endeavours to settle the dispute informally by agreement between the parties." == "In the event of any dispute or difference arising out of or in connection with or in relation to this Agreement or the existence, validity, termination, application or interpretation of this Agreement or any of its provisions, both parties shall use their best endeavours to settle the dispute informally by agreement between the parties."

@rule("s115", "s116", otherwise="Contradiction")
def check_final_clause():
    return "IN WITNESS WHEREOF the duly authorised representatives of the parties hereto have executed this Agreement as of the day and year first above written." == "IN WITNESS WHEREOF the duly authorised representatives of the parties hereto have executed this Agreement as of the day and year first above written."

query = check_confidentiality_clause() and check_data_protection_clause() and check_dispute_resolution_clause() and check_final_clause()
